/* ---------------- LabelSegments (rich consent paragraph) ----------------- */

/**
 * The inline runs of a segmented label. Extracted from Checkbox, where it was
 * an IIFE inside JSX carrying three nested ternaries (Sonar S3358) and most of
 * the component's cognitive complexity (S3776).
 */
function LabelSegments({
  segments,
  linkTargets,
  onLinkPress,
  lineHeight,
}: Readonly<
  OrUndefined<{
    segments: LabelSegment[];
    linkTargets?: string[];
    onLinkPress?: (target: string) => void;
    /** the paragraph's leading, inherited by a sized segment (see below). */
    lineHeight?: number;
  }>
>) {
  // a segment's identity is where it STARTS in the paragraph — stable across
  // re-renders, and unique even when two segments share text (S6479). The
  // offsets and the link ordinals are summed in a plain loop before the JSX:
  // a variable reassigned inside a render's map is react-hooks/immutability.
  let linkIdx = -1;
  let at = 0;
  const runs: Array<{ seg: LabelSegment; key: string; target: string | undefined }> = [];
  for (const seg of segments) {
    const isLink = Boolean(seg.href) || seg.underline === true;
    if (isLink) linkIdx += 1;
    runs.push({
      seg,
      key: 'seg@' + at,
      target: isLink ? segmentTarget(linkIdx, linkTargets) : undefined,
    });
    at += (seg.text ?? '').length;
  }
  return (
    <>
      {runs.map(({ seg, key, target }) => (
        <Text
          key={key}
          onPress={segmentPress(seg, target, onLinkPress)}
          style={segmentStyle(seg, lineHeight)}
        >
          {seg.text}
        </Text>
      ))}
    </>
  );
}

/** The FIRST link goes to the first target, every later one to the last. */
function segmentTarget(linkIdx: number, linkTargets?: string[]): string | undefined {
  if (!linkTargets || linkTargets.length === 0) return undefined;
  return linkIdx === 0 ? linkTargets[0] : linkTargets.at(-1);
}

/** An explicit href opens the browser; anything else defers to the screen. */
function segmentPress(
  seg: LabelSegment,
  target: string | undefined,
  onLinkPress?: (target: string) => void,
): (() => void) | undefined {
  if (seg.href) {
    return () => {
      fireAndForget(Linking.openURL(seg.href as string), 'open link');
    };
  }
  if (target && onLinkPress) return () => onLinkPress(target);
  return undefined;
}

/**
 * A run's leading.
 *
 * Its OWN lineHeight wins where the design gave it one. Otherwise a nested
 * <Text> that sets its own fontSize falls back to the FONT's default leading on
 * Android, so a consent paragraph whose links carry a size rendered shorter
 * than the design measured (3 lines at 32 rather than 37) — there the
 * paragraph's own line height is inherited instead. Three answers, so early
 * returns rather than a chained ternary (Sonar S3358).
 */
function segmentLeading(seg: LabelSegment, lineHeight?: number): { lineHeight?: number } {
  if (seg.lineHeight) return { lineHeight: s(seg.lineHeight) };
  /* v8 ignore if -- neither label hands the paragraph's leading in yet; wiring it changes what Android draws */
  if (seg.fontSize && lineHeight !== undefined) return { lineHeight };
  return {};
}

/**
 * A run's own inline style, in the order the design's fields override one
 * another.
 *
 * The return type is written out rather than inferred: this literal used to sit
 * in the JSX, where TextStyle typed it contextually and kept 'underline' and
 * '700' at their literal types. Out here nothing does, and inference would
 * widen both to string — which is a type error at the call site, not a silent
 * one, but only if the annotation is here to catch it.
 */
function segmentStyle(seg: LabelSegment, lineHeight?: number): TextStyle {
  return {
    ...(seg.color ? { color: seg.color } : {}),
    // s(), not the raw value. A segment's fontSize is a DESIGN pixel, and every
    // other length in a generated screen goes through s() before it reaches the
    // device. This one did not, so on native it rendered at full design size
    // while the text around it scaled — a 16px label inside a 1440-wide design
    // came out several times too large and overflowed its card. Identity on the
    // web target, where s(px) === px, so that output is unchanged.
    ...(seg.fontSize ? { fontSize: s(seg.fontSize) } : {}),
    // ...and the leading with it, by the same design-pixel rule.
    //
    ...segmentLeading(seg, lineHeight),
    // No "as const" on these two values (Sonar S4325: the assertion asserted
    // the type they already had).
    ...(seg.underline ? { textDecorationLine: 'underline' } : {}),
    // exact weight first, so the coarse bold flag (spread after) still wins
    // where both are set — the importer stays authoritative
    ...(seg.fontWeight === undefined ? {} : { fontWeight: rnWeightOf(seg.fontWeight) }),
    ...(seg.bold ? { fontWeight: '700' } : {}),
  };
}

/* ---------------- Checkbox ------------------------------------------------ */

/** unmet-required tint, shared by the box outline and the label. */
const ERROR_RED = '#ff3844';

/**
 * The tick box itself, lifted verbatim out of Checkbox: its zero-size guard,
 * its three outline states and the checked glyph were the bulk of what was
 * left of that component's cognitive complexity (Sonar S3776), and the glyph's
 * ternary sat inside the zero-size one (S3358).
 */
